```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'payment%' AND metric='k8s.container.restarts' AND value>0 ORDER BY time LIMIT 5", "claim": "Payment pod restart counter goes from 0 to 1 during the abnormal window; restarts stayed 0 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n FROM normal_traces WHERE service_name='payment' GROUP BY 1,2 UNION ALL SELECT 'abnormal', service_name, count(*) FROM abnormal_traces WHERE service_name='payment' GROUP BY 1,2", "claim": "Payment emitted 32 spans in normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name='oteldemo.PaymentService/Charge' GROUP BY 1,2", "claim": "All 46 checkout calls to PaymentService/Charge end in Error during the incident."}
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, min(time) t0, max(time) t1 FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('dns.lookup','grpc.oteldemo.ProductReviewService/GetProductReviews') GROUP BY 1,2,3", "claim": "Frontend dns.lookup spans error 9 times; all 43 GetProductReviews gRPC calls fail with Error status."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='GET /api/product-reviews/[productId]/index' GROUP BY 1,2,3", "claim": "Every GET /api/product-reviews request at frontend returns a 5xx status in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {"from": "payment", "to": "checkout", "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('oteldemo.CheckoutService/PlaceOrder','oteldemo.PaymentService/Charge') GROUP BY 1,2", "claim": "Checkout PlaceOrder and PaymentService/Charge spans both show 46 errors, with Charge failing first."}]},
    {"from": "checkout", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST /api/checkout' GROUP BY 1,2,3", "claim": "Frontend POST /api/checkout returns 500 on 45 requests, matching the failed PlaceOrder calls to checkout."}]},
    {"from": "frontend", "to": "frontend-proxy", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY 1,2,3", "claim": "Frontend-proxy ingress spans return 116 server errors, which carry the frontend checkout and product-review failures to users."}]}
  ]
}
```

